[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <title>CreativeHub — Online Classes for Creatives</title>
  <meta name="title" content="CreativeHub — Online Classes for Creatives">
  <meta name="description" content="Learn creative skills from industry professionals. Thousands of classes in illustration, design, photography, filmmaking and more. Start your free 7-day trial today.">

  <link rel="canonical" href="https://creativehub.com/">

  <meta property="og:type" content="website">
  <meta property="og:url" content="https://creativehub.com/">
