  <meta property="twitter:title" content="CreativeHub — Online Classes for Creatives">
  <meta property="twitter:description" content="Learn creative skills from industry professionals. Thousands of classes in illustration, design, photography, filmmaking and more.">
  <meta property="twitter:image" content="https://creativehub.com/og-image.jpg">

  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect fill='%23000000' width='100' height='100' rx='20'/><text y='70' x='50' text-anchor='middle' font-size='60' fill='%2355DA9B'>C</text></svg>">

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "name": "CreativeHub",
    "url": "https://creativehub.com/",
    "description": "Online learning community offering thousands of creative classes taught by industry professionals.",
    "potentialAction": {
      "@type": "SearchAction",
      "target": "https://creativehub.com/search?q={search_term_string}",
      "query-input": "required name=search_term_string"
    }
  }
  </script>

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is CreativeHub?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "CreativeHub is an online learning community with thousands of classes for creative and curious people, on topics including illustration, design, photography, video, freelancing, and more."
        }
      },
      {
        "@type": "Question",
        "name": "What is included in my membership?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "As a CreativeHub member, you'll have unlimited access to all classes to watch when and where you want, plus additional features such as offline viewing, access to a vibrant community of lifelong learners, and so much more."
        }
      },
      {
        "@type": "Question",
        "name": "What can I learn?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "CreativeHub has thousands of classes in everything from graphic design to cooking, productivity, filmmaking, content creation, UI/UX design, marketing, crafts, music, social media, and entrepreneurship."
        }
      },
      {
        "@type": "Question",
        "name": "What happens after my trial is over?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "After your trial ends, your annual CreativeHub membership begins. You'll be billed for the year in full, so you can enjoy continuous access to creative classes year-round."
        }
      },
      {
        "@type": "Question",
        "name": "Can I teach on the platform?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes! CreativeHub teachers are everyday creatives and professionals who want to share their passion and the skills they've gained with a community of eager learners."
        }
      }
    ]
  }
  </script>

  <style>
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --black: #000000;
      --green: #55DA9B;
      --purple: #5620C1;
      --white: #FFFFFF;
      --gray-100: #F7F7F7;
      --gray-200: #E5E5E5;
      --gray-300: #CCCCCC;
      --gray-400: #999999;
      --gray-500: #666666;
      --gray-600: #444444;
      --gray-700: #333333;
      --gray-800: #1A1A1A;
      --coral: #FF6B5B;
      --yellow: #FFD93D;
      --orange: #FF9F43;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--white);
      color: var(--gray-700);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    img {
      max-width: 100%;
      display: block;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(0, 0, 0, 0.95);
      backdrop-filter: blur(10px);
      padding: 0 24px;
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 24px;
      color: var(--white);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 800;
      color: var(--black);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav a {
      color: var(--gray-300);
      font-weight: 500;
      font-size: 15px;
      transition: color 0.2s;
    }

    .nav a:hover {
      color: var(--white);
    }

    .nav-buttons {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-ghost {
      background: transparent;
      border: none;
      color: var(--gray-300);
      font-weight: 600;
      font-size: 15px;
      cursor: pointer;
      padding: 8px 16px;
      transition: color 0.2s;
    }

    .btn-ghost:hover {
      color: var(--white);
    }

    .btn-primary {
      background: var(--green);
      color: var(--black);
      border: none;
      font-weight: 700;
      font-size: 15px;
      padding: 10px 24px;
      border-radius: 50px;
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(85, 218, 155, 0.4);
    }

    /* Hero */
    .hero {
      background: var(--black);
      min-height: 100vh;
      padding: 140px 24px 80px;
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      left: -20%;
      width: 60%;
      height: 100%;
      background: radial-gradient(ellipse, rgba(86, 32, 193, 0.3) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      top: 20%;
      right: -20%;
      width: 50%;
      height: 80%;
      background: radial-gradient(ellipse, rgba(85, 218, 155, 0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 900px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85, 218, 155, 0.15);
      border: 1px solid rgba(85, 218, 155, 0.3);
      color: var(--green);
      padding: 8px 16px;
      border-radius: 50px;
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 32px;
    }

    .hero-badge::before {
      content: '';
      width: 8px;
      height: 8px;
      background: var(--green);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.5; }
    }

    .hero h1 {
      font-size: clamp(40px, 8vw, 72px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.1;
      margin-bottom: 24px;
      letter-spacing: -2px;
    }

    .hero h1 span {
      background: linear-gradient(135deg, var(--green), var(--purple));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-subtitle {
      font-size: 20px;
      color: var(--gray-400);
      margin-bottom: 40px;
      font-weight: 500;
    }

    .hero-ctas {
      display: flex;
      flex-wrap: wrap;
      gap: 16px;
      justify-content: center;
      margin-bottom: 48px;
    }

    .btn-google {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      background: var(--white);
      color: var(--gray-700);
      border: none;
      font-weight: 700;
      font-size: 16px;
      padding: 14px 28px;
      border-radius: 50px;
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-google:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(255, 255, 255, 0.3);
    }

    .btn-google svg {
      width: 20px;
      height: 20px;
    }

    .btn-email {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--green);
      color: var(--black);
      border: none;
      font-weight: 700;
      font-size: 16px;
      padding: 14px 28px;
      border-radius: 50px;
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-email:hover {
      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(85, 218, 155, 0.4);
    }

    .hero-legal {
      font-size: 12px;
      color: var(--gray-500);
      max-width: 500px;
      line-height: 1.5;
    }

    /* Category Pills */
    .category-pills {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
      margin-top: 48px;
    }

    .category-pill {
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.1);
      color: var(--gray-300);
      padding: 10px 20px;
      border-radius: 50px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.2s;
    }

    .category-pill:hover {
      background: rgba(85, 218, 155, 0.2);
      border-color: var(--green);
      color: var(--green);
    }

    /* Features */
    .features {
      padding: 100px 24px;
      background: var(--white);
    }

    .features-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-label {
      display: inline-block;
      background: rgba(85, 218, 155, 0.1);
      color: var(--green);
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      padding: 8px 16px;
      border-radius: 50px;
      margin-bottom: 20px;
    }

    .section-title {
      font-size: clamp(32px, 5vw, 48px);
      font-weight: 800;
      color: var(--black);
      line-height: 1.2;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: 18px;
      color: var(--gray-500);
      max-width: 600px;
      margin-bottom: 48px;
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .feature-card {
      background: var(--gray-100);
      border-radius: 20px;
      padding: 32px;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--green), var(--purple));
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .feature-icon svg {
      width: 28px;
      height: 28px;
      color: var(--white);
    }

    .feature-card h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 8px;
    }

    .feature-card p {
      color: var(--gray-500);
      font-size: 15px;
      line-height: 1.6;
    }

    /* Stats */
    .stats {
      background: var(--black);
      padding: 80px 24px;
    }

    .stats-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 48px;
    }

    .stat-item {
      text-align: center;
    }

    .stat-value {
      font-size: clamp(48px, 8vw, 72px);
      font-weight: 800;
      color: var(--white);
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-value span {
      background: linear-gradient(135deg, var(--green), var(--purple));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .stat-label {
      font-size: 16px;
      color: var(--gray-400);
      font-weight: 500;
    }

    @media (max-width: 768px) {
      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 40px;
      }
    }

    /* Courses */
    .courses {
      padding: 100px 24px;
      background: var(--gray-100);
    }

    .courses-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .courses-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .course-tabs {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px;
      margin-bottom: 40px;
    }

    .course-tab {
      background: var(--white);
      border: 2px solid transparent;
      color: var(--gray-500);
      font-weight: 600;
      font-size: 14px;
      padding: 10px 20px;
      border-radius: 50px;
      cursor: pointer;
      transition: all 0.2s;
    }

    .course-tab:hover {
      border-color: var(--gray-300);
      color: var(--gray-700);
    }

    .course-tab.active {
      background: var(--black);
      color: var(--white);
      border-color: var(--black);
    }

    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }

    .course-card {
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .course-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
    }

    .course-thumbnail {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, var(--purple), var(--green));
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .course-thumbnail::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .course-thumbnail-icon {
      width: 48px;
      height: 48px;
      background: rgba(255, 255, 255, 0.2);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .course-thumbnail-icon svg {
      width: 24px;
      height: 24px;
      color: var(--white);
    }

    .course-info {
      padding: 20px;
    }

    .course-category {
      font-size: 12px;
      font-weight: 700;
      color: var(--purple);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }

    .course-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--black);
      line-height: 1.4;
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 13px;
      color: var(--gray-400);
    }

    .course-instructor {
      font-weight: 500;
    }

    .course-stats {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .course-stat {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .course-stat svg {
      width: 14px;
      height: 14px;
    }

    /* Creative Feed */
    .creative-feed {
      padding: 100px 24px;
      background: var(--white);
    }

    .creative-feed-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .creative-feed-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 32px;
    }

    .feed-card {
      background: var(--gray-100);
      border-radius: 24px;
      padding: 40px;
      text-align: center;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .feed-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
    }

    .feed-icon {
      width: 80px;
      height: 80px;
      background: linear-gradient(135deg, var(--green), var(--purple));
      border-radius: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
    }

    .feed-icon svg {
      width: 40px;
      height: 40px;
      color: var(--white);
    }

    .feed-card h3 {
      font-size: 24px;
      font-weight: 800;
      color: var(--black);
      margin-bottom: 12px;
    }

    .feed-card p {
      color: var(--gray-500);
      font-size: 16px;
      line-height: 1.6;
    }

    /* Teachers */
    .teachers {
      padding: 100px 24px;
      background: var(--gray-100);
    }

    .teachers-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .teachers-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .teachers-carousel-wrapper {
      position: relative;
    }

    .teachers-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding: 8px 0 24px;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }

    .teachers-carousel::-webkit-scrollbar {
      display: none;
    }

    .teacher-card {
      flex: 0 0 280px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: 20px;
      padding: 32px;
      text-align: center;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .teacher-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
    }

    .teacher-avatar {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      margin: 0 auto 20px;
      background: linear-gradient(135deg, var(--purple), var(--green));
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
      font-weight: 800;
      color: var(--white);
    }

    .teacher-name {
      font-size: 18px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 4px;
    }

    .teacher-specialty {
      font-size: 14px;
      color: var(--gray-500);
      font-weight: 500;
    }

    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 24px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 2px solid var(--gray-300);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s;
    }

    .carousel-btn:hover {
      border-color: var(--black);
      background: var(--black);
    }

    .carousel-btn:hover svg {
      color: var(--white);
    }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
      color: var(--gray-500);
    }

    /* Testimonials */
    .testimonials {
      padding: 100px 24px;
      background: var(--white);
    }

    .testimonials-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .testimonials-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .testimonial-card {
      background: var(--gray-100);
      border-radius: 20px;
      padding: 32px;
    }

    .testimonial-quote {
      font-size: 16px;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 24px;
      font-style: italic;
    }

    .testimonial-quote::before {
      content: '"';
      font-size: 48px;
      font-weight: 800;
