      transform: translateY(-2px);
      box-shadow: 0 4px 20px rgba(85, 218, 155, 0.4);
    }

    /* FAQ */
    .faq {
      padding: 100px 24px;
      background: var(--gray-100);
    }

    .faq-inner {
      max-width: 800px;
      margin: 0 auto;
    }

