      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .faq-item {
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
    }

    .faq-question {
      width: 100%;
      background: none;
      border: none;
      padding: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      cursor: pointer;
      font-size: 16px;
      font-weight: 700;
      color: var(--black);
      text-align: left;
      transition: background 0.2s;
    }

    .faq-question:hover {
      background: var(--gray-100);
    }

    .faq-icon {
      width: 24px;
      height: 24px;
      flex-shrink: 0;
      position: relative;
    }

    .faq-icon::before,
    .faq-icon::after {
      content: '';
      position: absolute;
      background: var(--gray-500);
      transition: transform 0.3s;
    }

    .faq-icon::before {
      width: 16px;
      height: 2px;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
    }

    .faq-icon::after {
      width: 2px;
      height: 16px;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
    }

    .faq-item.open .faq-icon::after {
      transform: translate(-50%, -50%) rotate(90deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease;
    }

    .faq-answer-inner {
      padding: 0 24px 24px;
      color: var(--gray-500);
      line-height: 1.7;
    }

