  <script>
    // FAQ Accordion - only one item open at a time
    document.querySelectorAll('.faq-question').forEach(button => {
      button.addEventListener('click', () => {
        const faqItem = button.parentElement;
        const isOpen = faqItem.classList.contains('open');

        // Close all other items
        document.querySelectorAll('.faq-item').forEach(item => {
          item.classList.remove('open');
          item.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
        });

        // Toggle current item
        if (!isOpen) {
          faqItem.classList.add('open');
          button.setAttribute('aria-expanded', 'true');
        }
      });
    });

    // Course Category Tabs
    document.querySelectorAll('.course-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        // Update active tab
        document.querySelectorAll('.course-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        // Filter courses
        const category = tab.dataset.category;
        document.querySelectorAll('.course-card').forEach(card => {
          const categories = card.dataset.categories || '';
          if (category === 'featured' || categories.includes(category)) {
            card.style.display = 'block';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });

    // Teacher Carousel Navigation
    const carousel = document.getElementById('teacherCarousel');
    const prevBtn = document.getElementById('prevTeacher');
    const nextBtn = document.getElementById('nextTeacher');
    const cardWidth = 304; // 280px card + 24px gap

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -cardWidth, behavior: 'smooth' });
    });

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: cardWidth, behavior: 'smooth' });
    });

    // Hero CTA interactions (placeholder for actual OAuth/email flow)
    document.querySelector('.btn-google').addEventListener('click', () => {
      alert('Continue with Google - OAuth flow would initiate here');
    });

    document.querySelector('.btn-email').addEventListener('click', () => {
      alert('Continue with email - Sign up form would appear here');
    });
  </script>
